Voici un exemple de script Python simple qui simule le comportement d’un assistant juridique spécialisé en droit du travail français, avec une logique de réponse basée sur des recherches de textes et des calculs de préavis/indemnité via des fonctions internes simulées.

```python
from dataclasses import dataclass
from typing import Optional, List


@dataclass
class Article:
    numero: str
    source: str
    texte: str
    lien: Optional[str] = None


class AssistantJuridique:
    def __init__(self):
        self.history: List[str] = []

    def search_code(self, query: str, source: Optional[str] = None):
        # Simulation simplifiée
        return [
            Article("L1234-1", "code", "Durée minimale du préavis selon l'ancienneté."),
            Article("L1234-9", "code", "Indemnité de licenciement sous conditions d'ancienneté."),
        ]

    def get_article(self, num: str, source: Optional[str] = None):
        # Simulation simplifiée
        database = {
            "L1234-1": Article("L1234-1", "code", "Le délai de préavis varie selon l'ancienneté du salarié."),
            "L1234-9": Article("L1234-9", "code", "Le salarié a droit à une indemnité de licenciement..."),
        }
        return database.get(num, None)

    def preavis(self, anciennete_mois: int, statut: str = "normal"):
        if statut in ("faute_grave", "faute_lourde"):
            return {"preavis_mois": 0}
        if anciennete_mois < 24:
            return {"preavis_mois": 1}
        return {"preavis_mois": 2}

    def indemnite_licenciement(self, anciennete_mois: int, salaire_ref: float, statut: str = "normal"):
        if statut in ("faute_grave", "faute_lourde") or anciennete_mois < 8:
            return {"indemnite": 0.0}
        annees = anciennete_mois / 12
        indemnite = salaire_ref * (1/4) * min(annees, 10)
        return {"indemnite": round(indemnite, 2)}

    def answer(self, question: str) -> str:
        self.history.append(question)

        # Réponse très simplifiée, basée sur des mots-clés
        q = question.lower()
        if "préavis" in q:
            result = self.preavis(anciennete_mois=18)
            return f"Le préavis minimum simulé est de {result['preavis_mois']} mois."
        if "indemnité" in q:
            result = self.indemnite_licenciement(anciennete_mois=24, salaire_ref=2500)
            return f"L'indemnité simulée est de {result['indemnite']} €."
        if "article" in q:
            art = self.get_article("L1234-1")
            if art:
                return f"{art.numero} : {art.texte}"
        return "Je ne dispose pas d'éléments suffisants pour répondre."


if __name__ == "__main__":
    assistant = AssistantJuridique()
    print(assistant.answer("Quel est le préavis ?"))
    print(assistant.answer("Quelle indemnité de licenciement ?"))
    print(assistant.answer("Parlez-moi de l'article L1234-1"))
```

